html.script:
$(document).ready(function() {
  const style = document.createElement('style');
  style.innerHTML = `@keyframes blink { 0% { opacity: 1; } 50% { opacity: 0; } 100% { opacity: 1; } }`;
  document.head.appendChild(style);

  var search = new splunkjs.mvc.SearchManager({
    id: "bruteforce-alert",
    search: `index=* OR index=wineventlog OR index=windows OR index=main sourcetype="WinEventLog:Security" EventCode=4625 | stats count`,
    earliest_time: "-1h@h",
    latest_time: "now"
  });
  search.on("search:done", function() {
    var results = search.data("results");
    results.on("data", function() {
      var failed = parseInt(results.data().rows[0][0]) || 0;
      var level = "FAIBLE";
      var color = "#00FF00";
      var showAlert = false;
      if (failed > 50) { level = "MOYEN"; color = "#FFFF00"; }
      if (failed > 100) { level = "ÉLEVÉ"; color = "#FF8000"; }
      if (failed > 200) { level = "CRITIQUE"; color = "#FF0000"; showAlert = true; }
      $("#threat-text").text(level).css("color", color);
      if (showAlert) $("#alert-flash").show(); else $("#alert-flash").hide();
    });
  });
  search.startSearch();
});

$(document).ready(function() {
  var search = new splunkjs.mvc.SearchManager({
    id: "heatmap-search",
    search: "(index=* OR index=wineventlog OR index=windows OR index=main) (sourcetype=\"WinEventLog:Security\" OR sourcetype=\"XmlWinEventLog:Microsoft-Windows-Sysmon/Operational\") $host_token$ | timechart span=1d count",
    cache: true
  });
  search.on("search:done", function() {
    var results = search.data("results");
    if (results) {
      results.on("data", function() {
        var data = {};
        var rows = results.data().rows;
        rows.forEach(function(row) {
          var timestamp = parseInt(row[0]) * 1000;
          var count = parseInt(row[1]) || 0;
          data[timestamp] = count;
        });
        new CalHeatmap().paint({
          itemSelector: "#heatmap-calendar",
          theme: "dark",
          domain: "month",
          subDomain: "day",
          data: data,
          date: { start: new Date(new Date().getFullYear(new Date().getFullYear() - 1)) },
          range: 13,
          cellSize: 18,
          legend: [100, 1000, 5000, 10000],
          legendColors: { base: "#333", min: "#144932", max: "#00FF00" }
        });
      });
    }
  });
  search.startSearch();
});
